package com.mannvaasam.controller;
import com.mannvaasam.model.*; import com.mannvaasam.repo.*; import com.mannvaasam.service.CurrentUserService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/buyers/addresses") public class AddressController { final AddressRepository repo; final CurrentUserService current; public AddressController(AddressRepository r,CurrentUserService c){repo=r;current=c;}
@GetMapping public List<Address> all(){return repo.findByUserOrderByPrimaryAddressDescIdDesc(current.get());}
@PostMapping public Address add(@RequestBody Address a){a.id=null;a.user=current.get();if(a.primaryAddress){repo.findByUserOrderByPrimaryAddressDescIdDesc(a.user).forEach(x->x.primaryAddress=false);}return repo.save(a);}
@PutMapping("/{id}") public Address update(@PathVariable Long id,@RequestBody Address in){Address a=repo.findByIdAndUser(id,current.get()).orElseThrow(()->new IllegalArgumentException("Address not found"));a.addressLine=in.addressLine;a.city=in.city;a.state=in.state;a.pincode=in.pincode;a.latitude=in.latitude;a.longitude=in.longitude;a.primaryAddress=in.primaryAddress;if(a.primaryAddress)repo.findByUserOrderByPrimaryAddressDescIdDesc(a.user).stream().filter(x->!x.id.equals(id)).forEach(x->x.primaryAddress=false);return repo.save(a);}
@DeleteMapping("/{id}") public Map<String,String> delete(@PathVariable Long id){Address a=repo.findByIdAndUser(id,current.get()).orElseThrow(()->new IllegalArgumentException("Address not found"));repo.delete(a);return Map.of("message","Address deleted");}}
